import os, json, math, random, statistics
import numpy as np

# Physical constants (SI)
G = 6.67430e-11          # m³·kg⁻¹·s⁻²
c = 2.99792458e8         # m·s⁻¹
hbar = 1.054571817e-34   # J·s
k_B = 1.380649e-23       # J·K⁻¹
M_sun = 1.98847e30       # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def photon_sphere_radius(M):
    return 1.5 * schwarzschild_radius(M)

def critical_impact_parameter(M):
    # b_crit = 3*sqrt(3) * GM / c^2
    return 3 * math.sqrt(3) * G * M / c**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def random_event_probability(p):
    return random.random() < p

def run_trials(M, N_trials=10000, p_crit=1e-5):
    b_crit = critical_impact_parameter(M)
    hits = 0
    for _ in range(N_trials):
        if random_event_probability(p_crit):
            hits += 1
    return hits / N_trials

if __name__ == "__main__":
    masses = {
        "Sun": M_sun,
        "10 Solar masses": 10 * M_sun,
        "100 Solar masses": 100 * M_sun
    }
    print("--- Black Hole Critical Impact Parameter Test ---")
    for name, M in masses.items():
        b_crit_m = critical_impact_parameter(M)
        print(f"{name}: b_crit = {b_crit_m:.3e} m")
    print("\n--- Hawking Temperature Test ---")
    for name, M in masses.items():
        T = hawking_temperature(M)
        print(f"{name}: Hawking temperature = {T:.3e} K")
    print("\n--- Random Event Consistency Test (p = 1e-5) ---")
    for name, M in masses.items():
        prob = run_trials(M)
        print(f"{name}: measured probability ≈ {prob:.6f} (expected ~1e-5)")
